impl Iterator for Counter {
    type ___ = u32;

    fn next(&mut self) -> Option<Self::Item> {
        None
    }
}

use std::ops::Add;

#[derive(Debug, PartialEq)]
struct Coin(u32);

impl Add for Coin {
    type Output = Coin;
    fn add(self, rhs: Coin) -> Coin {
        Coin(self.0 + rhs.0)
    }
}

fn main() {
    let total = Coin(3) + Coin(4);
    println!("{}", total.0);
}

trait Greet {
    fn label() -> String;
}

